import{_ as s,o as t,c as i,a2 as n}from"./chunks/framework.Bqj8z1Xs.js";const g=JSON.parse('{"title":"Refining an issue","description":"","frontmatter":{},"headers":[],"relativePath":"docs/agents/refining-issues.md","filePath":"docs/agents/refining-issues.md"}'),a={name:"docs/agents/refining-issues.md"};function o(d,e,h,l,r,c){return t(),i("div",null,[...e[0]||(e[0]=[n(`<h1 id="refining-an-issue" tabindex="-1">Refining an issue <a class="header-anchor" href="#refining-an-issue" aria-label="Permalink to &quot;Refining an issue&quot;">​</a></h1><p>How an agent turns a <strong>Quick idea</strong> (a few words, label <code>needs-triage</code>) into an agent-ready issue. It runs by hand: the maintainer says &quot;refine #N&quot; to an agent session. Nothing runs automatically when an idea is opened.</p><p>An issue written with the Feature or Bug form is already structured; refine it the same way when something is missing, and leave the parts that are fine.</p><h2 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to &quot;Steps&quot;">​</a></h2><ol><li><strong>Read the issue and its comments.</strong> The maintainer&#39;s words are the requirement; do not widen them.</li><li><strong>Read the context.</strong> <code>CONTEXT.md</code> for the terms, the ADRs and docs of the area (<code>docs/agents/areas.md</code> says which), and the code and mockups the idea touches. Use the terms of <code>CONTEXT.md</code> in the rewritten issue.</li><li><strong>Check the house rules</strong> from <code>CLAUDE.md</code> that the idea implies: <ul><li>every user-facing string in English and French;</li><li>a new screen or redesign starts as a mockup in <code>design/mockups/drafts/</code>;</li><li>logic goes in shared Kotlin with a test;</li><li>a schema change is a migration, and existing phones keep their data;</li><li>Poulpy is never guilt (blue side for pain or rehab, crimson with an icon for errors).</li></ul></li><li><strong>Rewrite the issue</strong> (title and body) to the Agent brief shape below.</li><li><strong>Set the labels and milestone</strong>, then comment with what you changed and, if you set <code>needs-info</code>, the questions.</li></ol><h2 id="agent-brief-shape" tabindex="-1">Agent brief shape <a class="header-anchor" href="#agent-brief-shape" aria-label="Permalink to &quot;Agent brief shape&quot;">​</a></h2><div class="language-md vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## Agent brief</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">### What and why</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">What should be possible, from the person&#39;s point of view, and why.</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">### Decided</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Choices already made, so the implementing agent does not reopen them.</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">### Mockups</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Existing mockups to follow, or &quot;a draft comes first&quot; when a screen is new.</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">### Acceptance criteria</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [ ] One checkable line each.</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">### Out of scope</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">What this issue deliberately does not cover.</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">### Device test</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Only when it needs a phone or treadmill: what to check.</span></span></code></pre></div><p>Keep it short. An issue that takes more than one PR is split, with each part a sub-issue.</p><h2 id="labels-and-milestone" tabindex="-1">Labels and milestone <a class="header-anchor" href="#labels-and-milestone" aria-label="Permalink to &quot;Labels and milestone&quot;">​</a></h2><p>Only labels and milestones listed in <code>.github/labels.yml</code> exist; never invent one.</p><ul><li><strong>One type:</strong> <code>bug</code>, <code>enhancement</code> or <code>documentation</code>.</li><li><strong>One state:</strong> see below.</li><li><strong>At least one area:</strong> <code>area:*</code>.</li><li><strong><code>device-test</code></strong> when the <em>Device test</em> section exists.</li><li><strong>One milestone</strong>, the phase it belongs to.</li></ul><table tabindex="0"><thead><tr><th>State</th><th>When</th></tr></thead><tbody><tr><td><code>ready-for-agent</code></td><td>Every section above is filled and nothing is left to decide</td></tr><tr><td><code>needs-info</code></td><td>A decision is missing</td></tr><tr><td><code>ready-for-human</code></td><td>Only a person can do it: a purchase, a test by hand</td></tr><tr><td><code>wontfix</code></td><td>It contradicts an ADR or the maintainer&#39;s stated direction; say which</td></tr></tbody></table><p>Remove <code>needs-triage</code> once another state is set.</p><h2 id="when-to-use-needs-info" tabindex="-1">When to use <code>needs-info</code> <a class="header-anchor" href="#when-to-use-needs-info" aria-label="Permalink to &quot;When to use \`needs-info\`&quot;">​</a></h2><p>Do not guess a decision that changes the product, the data or the cost. Set <code>needs-info</code>, and put a <strong>Decision needed</strong> section in the issue with explicit questions, each with the options and the default you would take if no answer comes. Then stop; the maintainer answers in a comment and the issue is refined again.</p><p>A detail an agent can settle by reading the code or the docs is not a question.</p>`,16)])])}const u=s(a,[["render",o]]);export{g as __pageData,u as default};
